#!/usr/bin/env python3
"""
Build a self-contained interactive HTML chart of NASA GISS global
temperature anomalies (1880–2025).

Data: NASA Goddard Institute for Space Studies — GISTEMP v4
      "GLOBAL Land-Ocean Temperature Index", annual (J-D) anomalies
      vs the 1951–1980 base period, in 0.01 degC.
Source file: /tmp/glb.txt (fetched from data.giss.nasa.gov)
"""
import math
import re

SRC = "/tmp/glb.txt"
OUT = "/workspace/temperature.html"

# ---- parse -------------------------------------------------------------
years, anoms = [], []
with open(SRC) as f:
    for line in f:
        m = re.match(r"\s*(\d{4})\s+(.+?)\s+(-?\d+|\\*\\*\\*\\*)\s+", line)
        if not m:
            continue
        year = int(m.group(1))
        jd = m.group(3)           # J-D annual mean column
        if jd in ("****", "***"):
            continue
        years.append(year)
        anoms.append(int(jd) / 100.0)

# keep complete years only (drop the partial 2026 row if present)
while years and years[-1] != 2025:
    years.pop()
    anoms.pop()

# ---- linear trend (degC per decade) ------------------------------------
n = len(years)
mx = sum(years) / n
my = sum(anoms) / n
sxx = sum((y - mx) ** 2 for y in years)
sxy = sum((y - mx) * (v - my) for y, v in zip(years, anoms))
slope = sxy / sxx                     # degC per year
per_decade = slope * 10
intercept = my - slope * mx

# ---- current value & warmest year --------------------------------------
latest_year, latest = years[-1], anoms[-1]
warm_idx = max(range(n), key=lambda i: anoms[i])
warm_year, warm_val = years[warm_idx], anoms[warm_idx]

# ---- series data as JS array --------------------------------------------
pts = ",".join(f"[{y},{v:.2f}]" for y, v in zip(years, anoms))
trend0 = intercept + slope * years[0]
trend1 = intercept + slope * years[-1]

def stat_cls(v):
    return "up" if v > 0 else "down"

rows = "".join(
    f"<tr><td data-v>{y}</td>"
    f"<td>{v:+.2f}</td><td class=\"delta {stat_cls(v)}\">{'&#9650;' if v>=0 else '&#9660;'} {abs(v):.2f}</td></tr>"
    for y, v in zip(years, anoms)
)

html = f"""<!DOCTYPE html>
<html lang="en" data-theme="light">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Global warming in one chart</title>
<style>
  :root {{
    color-scheme: light;
    --surface-1: #fcfcfb;   /* chart surface */
    --page:      #f9f9f7;
    --ink:       #0b0b0b;   /* primary */
    --ink-2:     #52514e;   /* secondary */
    --muted:     #898781;   /* axis / labels */
    --grid:      #e1e0d9;   /* hairline grid */
    --axis:      #c3c2b7;   /* baseline / axis */
    --series-1:  #2a78d6;   /* the line */
    --series-1-w:#2a78d6;
    --good:      #006300;
    --bad:       #e34948;
    --card:      #ffffff;
    --border:    rgba(11,11,11,0.10);
    --tooltip:   rgba(252,252,251,0.96);
    --shadow:    0 8px 28px rgba(20,20,20,0.10);
  }}
  @media (prefers-color-scheme: dark) {{
    :root:where(:not([data-theme="light"])) {{
      color-scheme: dark;
      --surface-1: #1a1a19;
      --page:      #0d0d0d;
      --ink:       #ffffff;
      --ink-2:     #c3c2b7;
      --muted:     #898781;
      --grid:      #2c2c2a;
      --axis:      #383835;
      --series-1:  #3987e5;
      --good:      #0ca30c;
      --bad:       #e66767;
      --card:      #161615;
      --border:    rgba(255,255,255,0.10);
      --tooltip:   rgba(26,26,25,0.96);
      --shadow:    0 8px 28px rgba(0,0,0,0.45);
    }}
  }}
  :root[data-theme="dark"] {{
    color-scheme: dark;
    --surface-1: #1a1a19;
    --page:      #0d0d0d;
    --ink:       #ffffff;
    --ink-2:     #c3c2b7;
    --muted:     #898781;
    --grid:      #2c2c2a;
    --axis:      #383835;
    --series-1:  #3987e5;
    --good:      #0ca30c;
    --bad:       #e66767;
    --card:      #161615;
    --border:    rgba(255,255,255,0.10);
    --tooltip:   rgba(26,26,25,0.96);
    --shadow:    0 8px 28px rgba(0,0,0,0.45);
  }}
  * {{ box-sizing: border-box; }}
  html,body {{ margin:0; padding:0; background:var(--page); }}
  body {{
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    color: var(--ink);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
  }}
  .wrap {{ max-width: 900px; margin: 0 auto; padding: 48px 24px 72px; }}
  header {{ margin-bottom: 28px; }}
  .eyebrow {{
    font-size: 12px; letter-spacing: .12em; text-transform: uppercase;
    color: var(--muted); font-weight: 600; margin: 0 0 10px;
  }}
  h1 {{ font-size: clamp(28px, 5vw, 40px); line-height: 1.08; margin: 0 0 10px; font-weight: 650; }}
  .lede {{ color: var(--ink-2); font-size: 16px; max-width: 66ch; margin: 0; }}
  .hero {{ display:flex; gap:6px; align-items:baseline; margin: 22px 0 4px; flex-wrap: wrap; }}
  .hero-num {{ font-size: 46px; font-weight: 650; line-height:1; }}
  .hero-unit {{ color: var(--muted); font-size: 14px; }}
  .hero-delta {{ font-size: 17px; font-weight:600; }}
  .delta.up  {{ color: var(--good); }}
  .delta.down{{ color: var(--bad); }}
  .card {{
    background: var(--card); border: 1px solid var(--border);
    border-radius: 14px; padding: 22px 22px 12px;
    box-shadow: var(--shadow);
  }}
  .card-tools {{ display:flex; justify-content:space-between; align-items:center;
    gap:16px; flex-wrap:wrap; margin-bottom: 6px;
    font-size: 13px; color: var(--ink-2);
  }}
  .mode-toggle {{ border:1px solid var(--border); background:transparent; color:var(--ink-2);
    font-family:inherit; font-size:13px; padding:6px 12px; border-radius:999px; cursor:pointer; }}
  .mode-toggle:hover {{ color: var(--ink); border-color: var(--muted); }}
  .legend {{ display:flex; gap:18px; align-items:center; font-size:13px; color:var(--ink-2); }}
  .legend .key {{ display:inline-flex; align-items:center; gap:7px; }}
  .legend .swatch {{ width:18px; height:2px; border-radius:2px; background:var(--series-1); display:inline-block; }}
  .legend .trend-dot {{ width:7px; height:7px; border-radius:50%; background:var(--series-1); display:inline-block; }}
  svg {{ display:block; width:100%; height:auto; }}
  /* mark & chrome tokens */
  .grid {{ stroke: var(--grid); stroke-width:1; }}
  .axis {{ stroke: var(--axis); stroke-width:1; }}
  .zero {{ stroke: var(--axis); stroke-width:1; }}
  .ytick {{ fill: var(--muted); font-size:11px; }}
  .xtick {{ fill: var(--muted); font-size:11px; }}
  .area {{ fill: var(--series-1); opacity:.10; }}
  .line {{ fill:none; stroke: var(--series-1); stroke-width:2; stroke-linecap:round; stroke-linejoin:round; }}
  .trend {{ fill:none; stroke: var(--series-1); stroke-width:2; stroke-dasharray:5 5; opacity:.8; }}
  .trend-dot {{ fill: var(--surface-1); stroke: var(--series-1); stroke-width:2; }}
  .end-dot {{ fill: var(--series-1); }}
  .end-label {{ fill: var(--ink); font-size:12px; font-weight:600; }}
  .hover-band {{ opacity:0; pointer-events:all; }}
  .crosshair {{ stroke: var(--muted); stroke-width:1; opacity:0; pointer-events:none; }}
  .hover-pt {{ fill: var(--surface-1); stroke: var(--series-1); stroke-width:2; opacity:0; pointer-events:none; }}
  .footnote {{ color: var(--muted); font-size:12px; margin-top:10px; }}
  .table-wrap {{ margin-top: 26px; }}
  .table-wrap summary {{
    cursor:pointer; font-size:14px; font-weight:600; color:var(--ink-2);
    padding:10px 0; user-select:none; list-style:none;
  }}
  .table-wrap summary::-webkit-details-marker {{ display:none; }}
  .table-wrap summary:hover {{ color:var(--ink); }}
  table {{ width:100%; border-collapse:collapse; font-size:13px; }}
  th,td {{ text-align:right; padding:6px 10px; border-bottom:1px solid var(--grid);
    font-variant-numeric: tabular-nums; }}
  th {{ color: var(--muted); font-weight:600; font-size:11px; text-transform:uppercase; letter-spacing:.05em; }}
  td:first-child, th:first-child {{ text-align:left; }}
  tbody tr:nth-child(even) {{ background: color-mix(in srgb, var(--series-1) 3%, transparent); }}
  .cap {{ color: var(--muted); font-size:12px; margin-top:8px; }}
  #tip {{
    position:absolute; display:none; pointer-events:none; z-index:5;
    background:var(--tooltip); border:1px solid var(--border); border-radius:9px;
    padding:9px 12px; font-size:12px; box-shadow: var(--shadow); backdrop-filter: blur(4px);
  }}
  #tip .t-val {{ font-size:17px; font-weight:700; line-height:1.1; }}
  #tip .t-lab {{ color: var(--ink-2); margin-top:2px; }}
  .sr-only {{ position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0 0 0 0); }}
</style>
</head>
<body>
<div class="wrap">
  <header>
    <p class="eyebrow">NASA GISTEMP &middot; observational climate data</p>
    <h1>Global warming in one chart</h1>
    <p class="lede">
      Global land&#8209;ocean temperature anomaly, 1880&ndash;2025, relative to the
      1951&ndash;1980 average. The dashed line is the linear trend.
    </p>
    <div class="hero">
      <span class="hero-num hero-delta">&plus;{latest:.2f}&deg;C</span>
      <span class="hero-unit">{latest_year} anomaly</span>
    </div>
    <p class="hero hero-delta delta up" style="margin-top:0">
      Trend: &plus;{per_decade:.2f}&deg;C per decade
      &nbsp;·&nbsp; Warmest year on record: {warm_year} (&plus;{warm_val:.2f}&deg;C)
    </p>
  </header>

  <div class="card" style="position:relative">
    <div class="card-tools">
      <div class="legend">
        <span class="key"><span class="swatch"></span>Temperature anomaly</span>
        <span class="key"><span class="trend-dot"></span>&nbsp;Linear trend ({per_decade:+.2f}&deg;C / decade)</span>
      </div>
      <button class="mode-toggle" id="modebtn" type="button" aria-pressed="false">Dark mode</button>
    </div>

    <svg id="chart" role="img" aria-label="Line chart of global temperature anomaly from 1880 to 2025. The line rises from about minus half a degree to about plus one and a quarter degrees." viewBox="0 0 860 460" xmlns="http://www.w3.org/2000/svg">
    </svg>
    <div id="tip" role="status"></div>
    <p class="footnote">
      Anomalies in &deg;C vs the 1951&ndash;1980 base period. Source: NASA GISS
      GISTEMP v4 (GHCN&#8209;v4 + ERSST&#8209;v5), annual J&ndash;D means.
    </p>
  </div>

  <details class="table-wrap">
    <summary>Annual values &mdash; data table</summary>
    <div class="cap">Every value, sorted oldest to newest. Delta is relative to the 1951&ndash;1980 average.</div>
    <div style="max-height:420px; overflow:auto; border:1px solid var(--border); border-radius:10px;">
      <table>
        <thead><tr><th>Year</th><th>Anomaly (&deg;C)</th><th>Delta</th></tr></thead>
        <tbody>{rows}</tbody>
      </table>
    </div>
  </details>
</div>

<script>
(function(){{
  const SVG="http://www.w3.org/2000/svg";
  const DATA = [{pts}];
  const N = DATA.length;
  const YEARS = [ {years[0]}, {years[-1]} ];
  const trend = [ {trend0:.3f}, {trend1:.3f} ];

  const W=860, H=460, L=54, R=24, T=26, B=44;
  const PW=W-L-R, PH=H-T-B;
  const y0=Math.min(-0.5, Math.min(...DATA.map(d=>d[1]))-0.1);
  const y1=Math.max(1.25, Math.max(...DATA.map(d=>d[1]))+0.1);
  const xf = y=>L+PW*(y-YEARS[0])/(YEARS[1]-YEARS[0]);
  const yf = v=>T+PH*(y1-v)/(y1-y0);

  const chart=document.getElementById("chart");
  const svgRoot=document.querySelector(".card");
  const tip=document.getElementById("tip");
  let sel = typeof matchMedia!=="undefined" &&
    matchMedia("(prefers-color-scheme: dark)").matches ? "dark":"light";

  // ---- axes --------------------------------------------------------------
  function g(el,p){ el.setAttribute("transform",p); return el; }
  // y gridlines + ticks (0 to y1, plus the baseline)
  const nice=[];
  for(let v=-0.5; v<=y1+0.01; v+=0.25) nice.push(v);
  const yVals=[...new Set([...nice, 0].map(v=>Math.round(v*100)/100))];
  yVals.forEach(v=>{{
    const yy=yf(v);
    if(Math.abs(v)<0.0001){{
      const l=document.createElementNS(SVG,"line");
      l.setAttribute("x1",L);l.setAttribute("x2",W-R);l.setAttribute("y1",yy);l.setAttribute("y2",yy);
      l.setAttribute("class","zero"); chart.appendChild(l);
    }} else {{
      const l=document.createElementNS(SVG,"line");
      l.setAttribute("x1",L);l.setAttribute("x2",W-R);l.setAttribute("y1",yy);l.setAttribute("y2",yy);
      l.setAttribute("class","grid"); chart.appendChild(l);
    }}
    const t=document.createElementNS(SVG,"text");
    t.setAttribute("x",L-8);t.setAttribute("y",yy+4);t.setAttribute("text-anchor","end");
    t.setAttribute("class","ytick"); t.textContent = v>0 ? "+"+v.toFixed(2) : v.toFixed(2);
    chart.appendChild(t);
  }});
  // x ticks
  [1880,1900,1920,1940,1960,1980,2000,2020].forEach(yr=>{{
    const xx=xf(yr);
    const l=document.createElementNS(SVG,"line");
    l.setAttribute("x1",xx);l.setAttribute("x2",xx);l.setAttribute("y1",T);l.setAttribute("y2",T+PH);
    l.setAttribute("class","grid"); chart.appendChild(l);
    const t=document.createElementNS(SVG,"text");
    t.setAttribute("x",xx);t.setAttribute("y",H-B+18);t.setAttribute("text-anchor","middle");
    t.setAttribute("class","xtick"); t.textContent=yr; chart.appendChild(t);
  }});
  const bl=document.createElementNS(SVG,"line");
  bl.setAttribute("x1",L);bl.setAttribute("x2",W-R);bl.setAttribute("y1",T+PH);bl.setAttribute("y2",T+PH);
  bl.setAttribute("class","axis"); chart.appendChild(bl);

  // ---- area + line -------------------------------------------------------
  const ptsStr = DATA.map(d=>xf(d[0]).toFixed(1)+","+yf(d[1]).toFixed(1)).join(" ");
  const area=document.createElementNS(SVG,"polygon");
  area.setAttribute("class","area");
  area.setAttribute("points",
    L+","+yf(0)+" "+ptsStr+" "+ (W-R)+","+yf(0));
  chart.appendChild(area);

  const line=document.createElementNS(SVG,"polyline");
  line.setAttribute("class","line");
  line.setAttribute("points",ptsStr); chart.appendChild(line);

  // zero baseline label
  const zt=document.createElementNS(SVG,"text");
  zt.setAttribute("x",L+4);zt.setAttribute("y",yf(0)-5);zt.setAttribute("class","ytick");
  zt.textContent="1951–80 avg"; chart.appendChild(zt);

  // trend line
  const tr=document.createElementNS(SVG,"line");
  tr.setAttribute("x1",xf(YEARS[0]));tr.setAttribute("y1",yf(trend[0]));
  tr.setAttribute("x2",xf(YEARS[1]));tr.setAttribute("y2",yf(trend[1]));
  tr.setAttribute("class","trend"); chart.appendChild(tr);
  const tdot=document.createElementNS(SVG,"circle");
  tdot.setAttribute("cx",xf(YEARS[1]));tdot.setAttribute("cy",yf(trend[1]));tdot.setAttribute("r",4);
  tdot.setAttribute("class","trend-dot"); chart.appendChild(tdot);

  // end dot + direct label for the latest value
  const edot=document.createElementNS(SVG,"circle");
  edot.setAttribute("cx",xf(latest_year));edot.setAttribute("cy",yf(latest));
  edot.setAttribute("r",4.5);edot.setAttribute("class","end-dot"); chart.appendChild(edot);
  const lab=document.createElementNS(SVG,"text");
  lab.setAttribute("x",xf(latest_year)-10);lab.setAttribute("y",yf(latest)-12);
  lab.setAttribute("text-anchor","end");lab.setAttribute("class","end-label");
  lab.textContent="+"+latest.toFixed(2)+"°C"; chart.appendChild(lab);

  // ---- hover: crosshair + per-point hit bands ----------------------------
  const cross=document.createElementNS(SVG,"line");
  cross.setAttribute("x1",0);cross.setAttribute("x2",0);cross.setAttribute("y1",T);cross.setAttribute("y2",T+PH);
  cross.setAttribute("class","crosshair"); chart.appendChild(cross);
  const hp=document.createElementNS(SVG,"circle");
  hp.setAttribute("r",4.5);hp.setAttribute("class","hover-pt"); chart.appendChild(hp);

  const bands=[];
  DATA.forEach((d,i)=>{{
    const b=document.createElementNS(SVG,"rect");
    const bx = i===0 ? xf(d[0]) : (xf(d[0])+xf(DATA[i-1][0]))/2;
    const bxx = i===N-1 ? xf(d[0]) : (xf(d[0])+xf(DATA[i+1][0]))/2;
    b.setAttribute("x",Math.min(bx,bxx)); b.setAttribute("width",Math.abs(bxx-bx));
    b.setAttribute("y",T); b.setAttribute("height",PH);
    b.setAttribute("class","hover-band");
    b.setAttribute("fill","transparent");
    b.addEventListener("pointermove",e=>show(d[0],d[1],xf(d[0]),yf(d[1])));
    b.addEventListener("pointerleave",hide);
    b.addEventListener("focus",()=>show(d[0],d[1],xf(d[0]),yf(d[1]),true));
    b.addEventListener("blur",hide);
    b.setAttribute("tabindex","0");
    chart.appendChild(b); bands.push(b);
  }});

  function show(year,val,px,py){{
    cross.setAttribute("x1",px);cross.setAttribute("x2",px);
    cross.setAttribute("style","opacity:1");
    hp.setAttribute("cx",px);hp.setAttribute("cy",py);
    hp.setAttribute("style","opacity:1");
    tip.style.display="block";
    tip.innerHTML="<div class='t-val'>"+(val>=0?"+":"")+val.toFixed(2)+"&deg;C</div>"+
      "<div class='t-lab'>"+year+" &middot; vs 1951–80 avg</div>";
    // position within card, slide to keep on screen
    const rect=svgRoot.getBoundingClientRect();
    let tx=px+18, ty=py-30;
    const tw=tip.offsetWidth, th=tip.offsetHeight;
    if(tx+tw>rect.width-8) tx=px-18-tw;
    if(ty<th) ty=th+8;
    tip.style.left=tx+"px"; tip.style.top=ty+"px";
  }}
  function hide(){{
    cross.setAttribute("style","opacity:0");
    hp.setAttribute("style","opacity:0");
    tip.style.display="none";
  }}

  // ---- theme -------------------------------------------------------------
  function applyTheme(t){{
    document.documentElement.setAttribute("data-theme",t);
    document.getElementById("modebtn").textContent = t==="dark"?"Light mode":"Dark mode";
    document.getElementById("modebtn").setAttribute("aria-pressed",t==="dark");
  }}
  applyTheme(sel);
  document.getElementById("modebtn").addEventListener("click",()=>{{
    sel = sel==="dark"?"light":"dark"; applyTheme(sel);
  }});
}})();
</script>
</body>
</html>
"""
with open(OUT, "w") as f:
    f.write(html)

print(f"wrote {OUT}")
print(f"{n} years ({years[0]}–{years[-1]}), anomaly {anoms[0]:+.2f} → {anoms[-1]:+.2f} °C")
print(f"trend {per_decade:+.3f} °C/decade; warmest {warm_year} {warm_val:+.2f} °C; latest {latest_year} {latest:+.2f} °C")

