<script>
(function(){{
  const SVG="http://www.w3.org/2000/svg";
  const DATA = [{pts}];
  const N = DATA.length;
  const YEARS = [ {years[0]}, {years[-1]} ];
  const trend = [ {trend0:.3f}, {trend1:.3f} ];

  const W=860, H=460, L=54, R=24, T=26, B=44;
  const PW=W-L-R, PH=H-T-B;
  const y0=Math.min(-0.5, Math.min(...DATA.map(d=>d[1]))-0.1);
  const y1=Math.max(1.25, Math.max(...DATA.map(d=>d[1]))+0.1);
  const xf = y=>L+PW*(y-YEARS[0])/(YEARS[1]-YEARS[0]);
  const yf = v=>T+PH*(y1-v)/(y1-y0);

  const chart=document.getElementById("chart");
  const svgRoot=document.querySelector(".card");
  const tip=document.getElementById("tip");
  let sel = typeof matchMedia!=="undefined" &&
    matchMedia("(prefers-color-scheme: dark)").matches ? "dark":"light";

  // ---- axes --------------------------------------------------------------
  function g(el,p){ el.setAttribute("transform",p); return el; }
  // y gridlines + ticks (0 to y1, plus the baseline)
  const nice=[];
  for(let v=-0.5; v<=y1+0.01; v+=0.25) nice.push(v);
  const yVals=[...new Set([...nice, 0].map(v=>Math.round(v*100)/100))];
  yVals.forEach(v=>{{
    const yy=yf(v);
    if(Math.abs(v)<0.0001){{
      const l=document.createElementNS(SVG,"line");
      l.setAttribute("x1",L);l.setAttribute("x2",W-R);l.setAttribute("y1",yy);l.setAttribute("y2",yy);
      l.setAttribute("class","zero"); chart.appendChild(l);
    }} else {{
      const l=document.createElementNS(SVG,"line");
      l.setAttribute("x1",L);l.setAttribute("x2",W-R);l.setAttribute("y1",yy);l.setAttribute("y2",yy);
      l.setAttribute("class","grid"); chart.appendChild(l);
    }}
    const t=document.createElementNS(SVG,"text");
    t.setAttribute("x",L-8);t.setAttribute("y",yy+4);t.setAttribute("text-anchor","end");
    t.setAttribute("class","ytick"); t.textContent = v>0 ? "+"+v.toFixed(2) : v.toFixed(2);
    chart.appendChild(t);
  }});
  // x ticks
  [1880,1900,1920,1940,1960,1980,2000,2020].forEach(yr=>{{
    const xx=xf(yr);
    const l=document.createElementNS(SVG,"line");
    l.setAttribute("x1",xx);l.setAttribute("x2",xx);l.setAttribute("y1",T);l.setAttribute("y2",T+PH);
    l.setAttribute("class","grid"); chart.appendChild(l);
    const t=document.createElementNS(SVG,"text");
    t.setAttribute("x",xx);t.setAttribute("y",H-B+18);t.setAttribute("text-anchor","middle");
    t.setAttribute("class","xtick"); t.textContent=yr; chart.appendChild(t);
  }});
  const bl=document.createElementNS(SVG,"line");
  bl.setAttribute("x1",L);bl.setAttribute("x2",W-R);bl.setAttribute("y1",T+PH);bl.setAttribute("y2",T+PH);
  bl.setAttribute("class","axis"); chart.appendChild(bl);

  // ---- area + line -------------------------------------------------------
  const ptsStr = DATA.map(d=>xf(d[0]).toFixed(1)+","+yf(d[1]).toFixed(1)).join(" ");
  const area=document.createElementNS(SVG,"polygon");
  area.setAttribute("class","area");
  area.setAttribute("points",
    L+","+yf(0)+" "+ptsStr+" "+ (W-R)+","+yf(0));
  chart.appendChild(area);

  const line=document.createElementNS(SVG,"polyline");
  line.setAttribute("class","line");
  line.setAttribute("points",ptsStr); chart.appendChild(line);

  // zero baseline label
  const zt=document.createElementNS(SVG,"text");
  zt.setAttribute("x",L+4);zt.setAttribute("y",yf(0)-5);zt.setAttribute("class","ytick");
  zt.textContent="1951–80 avg"; chart.appendChild(zt);

  // trend line
  const tr=document.createElementNS(SVG,"line");
  tr.setAttribute("x1",xf(YEARS[0]));tr.setAttribute("y1",yf(trend[0]));
  tr.setAttribute("x2",xf(YEARS[1]));tr.setAttribute("y2",yf(trend[1]));
  tr.setAttribute("class","trend"); chart.appendChild(tr);
  const tdot=document.createElementNS(SVG,"circle");
  tdot.setAttribute("cx",xf(YEARS[1]));tdot.setAttribute("cy",yf(trend[1]));tdot.setAttribute("r",4);
  tdot.setAttribute("class","trend-dot"); chart.appendChild(tdot);

  // end dot + direct label for the latest value
  const edot=document.createElementNS(SVG,"circle");
  edot.setAttribute("cx",xf(latest_year));edot.setAttribute("cy",yf(latest));
  edot.setAttribute("r",4.5);edot.setAttribute("class","end-dot"); chart.appendChild(edot);
  const lab=document.createElementNS(SVG,"text");
  lab.setAttribute("x",xf(latest_year)-10);lab.setAttribute("y",yf(latest)-12);
  lab.setAttribute("text-anchor","end");lab.setAttribute("class","end-label");
  lab.textContent="+"+latest.toFixed(2)+"°C"; chart.appendChild(lab);

  // ---- hover: crosshair + per-point hit bands ----------------------------
  const cross=document.createElementNS(SVG,"line");
  cross.setAttribute("x1",0);cross.setAttribute("x2",0);cross.setAttribute("y1",T);cross.setAttribute("y2",T+PH);
  cross.setAttribute("class","crosshair"); chart.appendChild(cross);
  const hp=document.createElementNS(SVG,"circle");
  hp.setAttribute("r",4.5);hp.setAttribute("class","hover-pt"); chart.appendChild(hp);

  const bands=[];
  DATA.forEach((d,i)=>{{
    const b=document.createElementNS(SVG,"rect");
    const bx = i===0 ? xf(d[0]) : (xf(d[0])+xf(DATA[i-1][0]))/2;
    const bxx = i===N-1 ? xf(d[0]) : (xf(d[0])+xf(DATA[i+1][0]))/2;
    b.setAttribute("x",Math.min(bx,bxx)); b.setAttribute("width",Math.abs(bxx-bx));
    b.setAttribute("y",T); b.setAttribute("height",PH);
    b.setAttribute("class","hover-band");
    b.setAttribute("fill","transparent");
    b.addEventListener("pointermove",e=>show(d[0],d[1],xf(d[0]),yf(d[1])));
    b.addEventListener("pointerleave",hide);
    b.addEventListener("focus",()=>show(d[0],d[1],xf(d[0]),yf(d[1]),true));
    b.addEventListener("blur",hide);
    b.setAttribute("tabindex","0");
    chart.appendChild(b); bands.push(b);
  }});

  function show(year,val,px,py){{
    cross.setAttribute("x1",px);cross.setAttribute("x2",px);
    cross.setAttribute("style","opacity:1");
    hp.setAttribute("cx",px);hp.setAttribute("cy",py);
    hp.setAttribute("style","opacity:1");
    tip.style.display="block";
    tip.innerHTML="<div class='t-val'>"+(val>=0?"+":"")+val.toFixed(2)+"&deg;C</div>"+
      "<div class='t-lab'>"+year+" &middot; vs 1951–80 avg</div>";
    // position within card, slide to keep on screen
    const rect=svgRoot.getBoundingClientRect();
    let tx=px+18, ty=py-30;
    const tw=tip.offsetWidth, th=tip.offsetHeight;
    if(tx+tw>rect.width-8) tx=px-18-tw;
    if(ty<th) ty=th+8;
    tip.style.left=tx+"px"; tip.style.top=ty+"px";
  }}
  function hide(){{
    cross.setAttribute("style","opacity:0");
    hp.setAttribute("style","opacity:0");
    tip.style.display="none";
  }}

  // ---- theme -------------------------------------------------------------
  function applyTheme(t){{
    document.documentElement.setAttribute("data-theme",t);
    document.getElementById("modebtn").textContent = t==="dark"?"Light mode":"Dark mode";
    document.getElementById("modebtn").setAttribute("aria-pressed",t==="dark");
  }}
  applyTheme(sel);
  document.getElementById("modebtn").addEventListener("click",()=>{{
    sel = sel==="dark"?"light":"dark"; applyTheme(sel);
  }});
}})();
</script>
</body>
</html>
"""
