import asyncio
from playwright.async_api import async_playwright

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(args=["--no-sandbox"])
        page = await b.new_page(viewport={"width":1000,"height":1200})
        errors=[]
        page.on("console", lambda m: errors.append(m.text) if m.type=="error" else None)
        page.on("pageerror", lambda e: errors.append("PAGEERROR: "+str(e)))
        await page.goto("file:///workspace/temperature.html")
        await page.wait_for_timeout(500)

        # element presence
        info = await page.evaluate("""() => {
          const svg=document.getElementById('chart');
          const ns=svg.querySelectorAll('*').length;
          const line=document.querySelector('.line');
          const pts=document.querySelector('.line').getAttribute('points').split(' ').length;
          const area=!!document.querySelector('.area');
          const trend=!!document.querySelector('.trend');
          const dots=document.querySelectorAll('.end-dot, .trend-dot').length;
          const rect=svg.getBoundingClientRect();
          return {ns, pts, area, trend, dots, svgW:Math.round(rect.width), svgH:Math.round(rect.height)};
        }""")
        print("DOM:", info)

        # overflow check: does any text spill outside card/svg?
        over = await page.evaluate("""() => {
          const svg=document.getElementById('chart').getBoundingClientRect();
          const bad=[];
          document.querySelectorAll('svg text').forEach(t=>{
            const bb=t.getBoundingClientRect();
            if(bb.left<svg.left-2 || bb.right>svg.right+2 || bb.top<svg.top-2 || bb.bottom>svg.bottom+2)
              bad.push(t.textContent+":"+Math.round(bb.left)+","+Math.round(bb.top));
          });
          return bad.slice(0,10);
        }""")
        print("overflow texts:", over)

        # hover test - find a band near the data, dispatch pointermove
        hover = await page.evaluate("""() => {
          const band=document.querySelectorAll('.hover-band')[140]; // near last
          band.dispatchEvent(new PointerEvent('pointermove',{bubbles:true}));
          const tip=document.getElementById('tip');
          return {display:tip.style.display, text:tip.textContent};
        }""")
        print("hover:", hover)

        # click dark mode
        await page.click("#modebtn")
        theme = await page.evaluate("document.documentElement.getAttribute('data-theme')")
        btn = await page.evaluate("document.getElementById('modebtn').textContent")
        print("theme after click:", theme, "/", btn)

        # table
        trows = await page.evaluate("document.querySelectorAll('tbody tr').length")
        print("table rows:", trows)

        print("console errors:", errors if errors else "none")
        await b.close()

asyncio.run(main())

